import os,json,datetime,subprocess,urllib.request,hashlib
root=r'E:\WebAIBridge';backups=os.path.join(root,'app','data','backups')
out={'at':datetime.datetime.now().isoformat(timespec='seconds'),'audit':'detached_cutover_no_replay'}
x=subprocess.run(['git.exe','-C',root,'rev-parse','HEAD'],capture_output=True,text=True,timeout=5)
out['head']=x.stdout.strip()
x=subprocess.run(['git.exe','-C',root,'status','--porcelain=v1','-z','--untracked-files=all'],capture_output=True,timeout=7)
out['worktreeStatusSha256']=hashlib.sha256(x.stdout).hexdigest()
try:
 rows=[n for n in os.listdir(backups) if n.startswith('r42-cutover-') and os.path.isdir(os.path.join(backups,n))]
 out['r42backupCount']=len(rows)
 out['latestR42Backups']=sorted(rows,reverse=True)[:3]
except Exception as e:out['listError']=type(e).__name__
for tag,path in [('operator','/api/operator-lifecycle'),('supervisor','/api/supervisor-watchdog?detect=0'),('cutover','/api/projects/control-plane/cutover-r42/status')]:
 try:
  with urllib.request.urlopen('http://127.0.0.1:17448'+path,timeout=3) as f:z=json.load(f)
  if tag=='operator':out[tag]={'paused':z.get('queuePaused'),'mode':z.get('mode')}
  if tag=='supervisor':out[tag]={k:z.get('config',{}).get(k) for k in ('mode','enabled','allowAutonomousSend')}
  if tag=='cutover':out[tag]={k:z.get('cutoverState',{}).get(k) for k in ('status','targetSha','holdActive')}
 except Exception as e:out[tag]={'error':type(e).__name__}
print(json.dumps(out,ensure_ascii=True))
